package dashboard

import (
	"context"
	"fmt"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// topologyProvider fetches the declared topologies for the workspace. Each
// entry's Path is the on-disk system directory (the handler normalizes it to
// a root-relative identifier). Per-host failures are returned as messages
// alongside the successes so one broken host cannot hide the rest.
type topologyProvider func(ctx context.Context) (entries []topology.Entry, errs []string)

// hostGraphProvider returns the default provider: it finds every scaffolded
// system host under root and asks each one to print its declared topology.
// Hosts scaffolded before the graph verb existed simply fail, which surfaces as
// an error the UI renders.
//
// The mechanics live in topology.RunGraph, which deploy init shares. What stays
// here is the dashboard's policy: never fail, report per host.
func hostGraphProvider(root string) topologyProvider {
	return func(ctx context.Context) ([]topology.Entry, []string) {
		hosts, _ := template.ListSystemHosts(root)
		var entries []topology.Entry
		var errs []string
		for _, h := range hosts {
			t, err := topology.RunGraph(ctx, h.Path)
			if err != nil {
				errs = append(errs, fmt.Sprintf("%s: %v", displayPath(root, h.Path), err))
				continue
			}
			// The system directory is the workspace directory holding the
			// host: components are scaffolded as its siblings.
			entries = append(entries, topology.Entry{Path: filepath.Dir(h.Path), Topology: *t})
		}
		return entries, errs
	}
}

// displayPath shortens a host directory to its root-relative form for error
// messages, matching the identifier space the rest of the API uses.
func displayPath(root, p string) string {
	if rel, err := filepath.Rel(root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

import { useCallback, useEffect, useState } from 'react'
import { api, type DeployState, type Integration, type IntegrationDetail } from './api'
import { Sidebar } from './components/Sidebar'
import { DetailPanel } from './components/DetailPanel'
import { FlowView } from './components/FlowView'
import { TemplatesView } from './components/TemplatesView'
import { DarkModeIcon, LightModeIcon, SystemThemeIcon } from './icons'

const SIDEBAR_COLLAPSED_KEY = 'intropy.sidebar.collapsed'
const THEME_KEY = 'intropy.theme'

type View = 'catalog' | 'flow' | 'templates'

const VIEWS: { id: View; label: string }[] = [
  { id: 'catalog', label: 'Integration Catalog' },
  { id: 'flow', label: 'Integration Flow' },
  { id: 'templates', label: 'Templates' },
]

// Theme preference cycles light → dark → system. "system" follows the OS,
// resolved to a concrete light/dark value that drives both data-theme (CSS)
// and the flow canvas colorMode.
type ThemePref = 'light' | 'dark' | 'system'
const THEME_ORDER: ThemePref[] = ['light', 'dark', 'system']
const THEME_META: Record<ThemePref, { Icon: typeof LightModeIcon; label: string }> = {
  light: { Icon: LightModeIcon, label: 'Light' },
  dark: { Icon: DarkModeIcon, label: 'Dark' },
  system: { Icon: SystemThemeIcon, label: 'System' },
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

function resolveTheme(pref: ThemePref): 'light' | 'dark' {
  return pref === 'system' ? (prefersDark() ? 'dark' : 'light') : pref
}

export default function App() {
  const [integrations, setIntegrations] = useState<Integration[] | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  const [detail, setDetail] = useState<IntegrationDetail | null>(null)
  const [deployState, setDeployState] = useState<DeployState | null>(null)
  const [deployLoading, setDeployLoading] = useState(false)
  const [deployRefreshing, setDeployRefreshing] = useState(false)
  const [version, setVersion] = useState<string>('')
  const [error, setError] = useState<string | null>(null)
  const [collapsed, setCollapsed] = useState<boolean>(
    () => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === 'true',
  )
  const [view, setView] = useState<View>('catalog')
  const [theme, setTheme] = useState<ThemePref>(
    () => (localStorage.getItem(THEME_KEY) as ThemePref | null) ?? 'system',
  )
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>(() =>
    resolveTheme(theme),
  )

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed))
  }, [collapsed])

  // Apply the theme to <html> and track the resolved value. In system mode,
  // also follow live OS changes; explicit modes ignore them.
  useEffect(() => {
    localStorage.setItem(THEME_KEY, theme)
    const apply = () => {
      const resolved = resolveTheme(theme)
      document.documentElement.dataset.theme = resolved
      setResolvedTheme(resolved)
    }
    apply()
    if (theme !== 'system') return
    const mq = window.matchMedia('(prefers-color-scheme: dark)')
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [theme])

  const cycleTheme = () =>
    setTheme((t) => THEME_ORDER[(THEME_ORDER.indexOf(t) + 1) % THEME_ORDER.length])

  useEffect(() => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    api
      .health()
      .then((h) => setVersion(h.version))
      .catch(() => {})
  }, [])

  // Auto-select the first integration once the list loads.
  useEffect(() => {
    if (integrations && integrations.length > 0 && !selected) {
      setSelected(integrations[0].path)
    }
  }, [integrations, selected])

  useEffect(() => {
    if (!selected) {
      setDetail(null)
      return
    }
    setDetail(null)
    api
      .getIntegration(selected)
      .then(setDetail)
      .catch((e: unknown) => setError(errText(e)))
  }, [selected])

  // Deployment state loads on its own, because it costs its own thing: reading
  // it refreshes a GitOps checkout over the network, while the detail above is
  // local files. Keeping them apart lets the panel render straight away.
  //
  // A failed lookup is not an error banner: the reason travels inside the state
  // and belongs in the Deployment section, next to the Refresh that retries it.
  useEffect(() => {
    if (!selected) {
      setDeployState(null)
      return
    }
    setDeployState(null)
    setDeployLoading(true)
    let current = true
    api
      .deployState(selected)
      .then((s) => {
        if (current) setDeployState(s)
      })
      .catch((e: unknown) => {
        if (current) setDeployState({ error: errText(e), readAt: new Date().toISOString() })
      })
      .finally(() => {
        if (current) setDeployLoading(false)
      })
    // Selecting another integration while this is in flight must not let the
    // slower answer land on the newer selection.
    return () => {
      current = false
    }
  }, [selected])

  const refreshDeploy = useCallback(() => {
    if (!selected) return
    setDeployRefreshing(true)
    api
      .refreshDeployState(selected)
      .then(setDeployState)
      .catch((e: unknown) =>
        setDeployState({ error: errText(e), readAt: new Date().toISOString() }),
      )
      .finally(() => setDeployRefreshing(false))
  }, [selected])

  // A template create lands here: re-scan the workspace, then open the new
  // integration in the catalog.
  const onTemplateCreated = useCallback((path: string) => {
    api
      .listIntegrations()
      .then(setIntegrations)
      .catch((e: unknown) => setError(errText(e)))
    setSelected(path)
    setView('catalog')
  }, [])

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden />
          <span className="brand-name">Intropy</span>
          <span className="brand-sub">dashboard</span>
        </div>
        <nav className="nav">
          {VIEWS.map((v) => (
            <button
              key={v.id}
              className={`nav-item${view === v.id ? ' active' : ''}`}
              onClick={() => setView(v.id)}
              aria-current={view === v.id ? 'page' : undefined}
            >
              {v.label}
            </button>
          ))}
        </nav>
        <div className="topbar-end">
          {version && <span className="version">{version}</span>}
          <ThemeToggle theme={theme} onCycle={cycleTheme} />
        </div>
      </header>

      <div className="layout">
        {view === 'catalog' && (
          <Sidebar
            integrations={integrations}
            selected={selected}
            onSelect={setSelected}
            collapsed={collapsed}
            onToggle={() => setCollapsed((c) => !c)}
          />
        )}
        <main className="content">
          {error && <div className="banner error">{error}</div>}
          {view === 'catalog' && (
            <DetailPanel
              detail={detail}
              hasSelection={!!selected}
              deploy={{
                state: deployState,
                loading: deployLoading,
                refreshing: deployRefreshing,
                onRefresh: refreshDeploy,
              }}
            />
          )}
          {view === 'flow' && (
            <FlowView selected={selected} onSelect={setSelected} theme={resolvedTheme} />
          )}
          {view === 'templates' && <TemplatesView onCreated={onTemplateCreated} />}
        </main>
      </div>
    </div>
  )
}

// ThemeToggle cycles the theme preference. The current mode's glyph and a
// title communicate both the active choice and that clicking advances it.
function ThemeToggle({ theme, onCycle }: { theme: ThemePref; onCycle: () => void }) {
  const { Icon, label } = THEME_META[theme]
  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={onCycle}
      title={`Theme: ${label} (click to change)`}
      aria-label={`Theme: ${label}. Click to change.`}
    >
      <Icon className="icon" aria-hidden />
    </button>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

import { useEffect, useMemo, useState } from 'react'
import {
  Background,
  Controls,
  Handle,
  MarkerType,
  MiniMap,
  Position,
  ReactFlow,
  ReactFlowProvider,
  useNodesInitialized,
  useNodesState,
  useReactFlow,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import {
  api,
  type DaprComponent,
  type IntegrationDetail,
  type Topology,
  type TopologyReport,
} from '../api'
import {
  CloudIcon,
  CycleIcon,
  HardDriveIcon,
  HubIcon,
  InputIcon,
  MemoryIcon,
  OutputIcon,
  SyncAltIcon,
} from '../icons'
import { Combobox, type ComboOption } from './Combobox'
import { FlowDetail, type FlowSelection } from './FlowDetail'

interface Props {
  selected: string | null
  onSelect: (path: string) => void
  /** Resolved app theme; drives React Flow's chrome (controls, minimap, edges). */
  theme: 'light' | 'dark'
}

// Layout geometry. The layout is deterministic: components and the topics
// they publish/subscribe flow left-to-right by declared depth inside the
// system boundary, and external systems (via connectors) sit outside it.
const NODE_W = 300
const NODE_H = 84
const COL_GAP = 28
const ROW_GAP = 28
const GROUP_HEADER = 44
const GROUP_PAD = 20
const INFRA_W = 200
const INFRA_H = 76
const EXT_W = 184
const EXT_H = 72
const EXT_GAP = 96
const EXT_VGAP = 24

const WORKSPACE_KEY = '__workspace__'

/** Which way data crosses the system boundary for a component. */
type DataFlow = 'in' | 'out' | 'both' | 'internal'

// Boundary direction by declared component kind, used only to pick the card's
// directional glyph — never to invent wiring; every edge on the canvas comes
// from the declared topology.
const KIND_DATA_FLOW: Record<string, DataFlow> = {
  extractor: 'in',
  loader: 'out',
  transactional: 'both',
  transactionalintegration: 'both',
  aggregator: 'internal',
}

// dataFlowFor resolves a component kind to its boundary direction, ignoring
// case and hyphens (the topology library kebab-cases kinds, e.g.
// "transactional-integration").
function dataFlowFor(kind: string): DataFlow | undefined {
  return KIND_DATA_FLOW[kind.toLowerCase().replace(/-/g, '')]
}

// Directional glyph per data flow; integrations with no known flow keep the
// generic chip icon rather than guessing a direction.
const DATA_FLOW_ICONS: Record<DataFlow, typeof MemoryIcon> = {
  in: InputIcon,
  out: OutputIcon,
  both: SyncAltIcon,
  internal: CycleIcon,
}

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  dataFlow?: DataFlow
  selected: boolean
  /** Cron expression badge for schedule-triggered components (declared topology only). */
  trigger?: string
}

interface GroupNodeData extends Record<string, unknown> {
  title: string
  count: number
}

interface ExtNodeData extends Record<string, unknown> {
  name: string
  type: string
  direction?: DaprComponent['direction']
  /** Declared connector name — the inspector's join key to the topology's
   *  connectors[] and messageDocs. */
  connector?: string
}

interface TopicNodeData extends Record<string, unknown> {
  name: string
  /** Pub/sub component the topic lives on — with name, the inspector's join
   *  key into the topology's topics[]. */
  pubsub?: string
  /** Data entity carried on the topic, e.g. "RawProduct". */
  entity?: string
  /** Contract ref when the topic is a declared API (contract surface). */
  contract?: string
}

// systemKey/systemLabel identify a system by its domain/system folder pair so
// two different domains that reuse a system name stay distinct. Integrations
// scaffolded at the workspace root fall under a "Workspace" pseudo-system.
function systemKey(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join('/') || WORKSPACE_KEY
}

function systemLabel(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join(' / ') || 'Workspace'
}

// topologyFor picks the declared topology covering a system's integrations:
// the record whose directory contains every integration in the group. A
// record at the workspace root ('.') contains everything.
function topologyFor(
  items: IntegrationDetail[],
  topologies: Topology[],
): Topology | undefined {
  if (items.length === 0) return undefined
  return topologies.find((t) =>
    items.every(
      (it) => t.path === '.' || it.path === t.path || it.path.startsWith(t.path + '/'),
    ),
  )
}

export function FlowView({ selected, onSelect, theme }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [report, setReport] = useState<TopologyReport | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [refreshing, setRefreshing] = useState(false)
  const [system, setSystem] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])
  // What the inspector panel shows: a clicked topic or connector node.
  const [inspect, setInspect] = useState<FlowSelection | null>(null)

  // A different system means different topics/connectors — drop the inspector.
  useEffect(() => setInspect(null), [system])

  useEffect(() => {
    const fail = (e: unknown) => setError(e instanceof Error ? e.message : String(e))
    api.flow().then(setGraph).catch(fail)
    // The first topology fetch runs each host's graph verb (a dotnet build),
    // so this request can take a while — the loading state covers it.
    api.topologies().then(setReport).catch(fail)
  }, [])

  const refresh = () => {
    setRefreshing(true)
    api
      .refreshTopologies()
      .then(setReport)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
      .finally(() => setRefreshing(false))
  }

  const topologies = useMemo(() => report?.topologies ?? [], [report])

  // The dropdown lists every system present, with an integration count. When
  // a declared topology covers a group its system name is the authoritative
  // label, overriding the folder-derived one.
  const systems = useMemo<ComboOption[]>(() => {
    if (!graph) return []
    const groups = new Map<string, { opt: ComboOption; items: IntegrationDetail[] }>()
    for (const it of graph) {
      const key = systemKey(it)
      const g =
        groups.get(key) ?? { opt: { value: key, label: systemLabel(it), count: 0 }, items: [] }
      g.opt.count = (g.opt.count ?? 0) + 1
      g.items.push(it)
      groups.set(key, g)
    }
    for (const g of groups.values()) {
      const t = topologyFor(g.items, topologies)
      if (t) g.opt.label = t.system
    }
    return [...groups.values()]
      .map((g) => g.opt)
      .sort((a, b) => a.label.localeCompare(b.label))
  }, [graph, topologies])

  // Default to the first system once data lands.
  useEffect(() => {
    if (system === null && systems.length > 0) setSystem(systems[0].value)
  }, [systems, system])

  const items = useMemo(
    () => (graph && system ? graph.filter((it) => systemKey(it) === system) : []),
    [graph, system],
  )

  // Only a declared topology is drawn — there is no inferred fallback. A
  // system whose host produced no record renders the empty state below.
  const declared = useMemo(() => topologyFor(items, topologies), [items, topologies])
  const built = useMemo(
    () => (declared ? buildDeclaredGraph(declared, items) : { nodes: [], edges: [] }),
    [declared, items],
  )
  useEffect(() => setNodes(built.nodes), [built, setNodes])

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph || report === null) {
    return <p className="empty">Loading… (building system hosts on first run)</p>
  }
  if (graph.length === 0) {
    return <p className="empty">No integrations to visualise.</p>
  }

  return (
    <div className="flow-view">
      <div className="flow-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={systems}
          onChange={setSystem}
          placeholder="Select a system…"
        />
        <button
          type="button"
          className="flow-refresh"
          onClick={refresh}
          disabled={refreshing}
          title="Re-run each system host's graph verb"
        >
          {refreshing ? 'Refreshing…' : 'Refresh topology'}
        </button>
      </div>
      {report.errors?.length ? (
        <div className="banner error">
          {report.errors.map((e) => (
            <div key={e}>{e}</div>
          ))}
        </div>
      ) : null}
      {declared ? (
        <div className="flow-canvas">
          <ReactFlowProvider>
            <FlowCanvas
              nodes={nodes}
              edges={built.edges}
              onNodesChange={onNodesChange}
              onSelect={onSelect}
              onInspect={setInspect}
              fitSignal={system ?? ''}
              theme={theme}
            />
          </ReactFlowProvider>
          {inspect && (
            <FlowDetail
              selection={inspect}
              topology={declared}
              onClose={() => setInspect(null)}
            />
          )}
        </div>
      ) : (
        <p className="empty">
          No declared topology for this system. Make sure its system host
          supports the graph verb, then refresh.
        </p>
      )}
    </div>
  )
}

// FlowCanvas hosts the React Flow instance so it can refit the viewport once
// nodes are measured, and again whenever the selected system changes — the
// `fitView` prop alone fits at init while the async node list is still empty.
function FlowCanvas({
  nodes,
  edges,
  onNodesChange,
  onSelect,
  onInspect,
  fitSignal,
  theme,
}: {
  nodes: Node[]
  edges: Edge[]
  onNodesChange: Parameters<typeof ReactFlow>[0]['onNodesChange']
  onSelect: (path: string) => void
  onInspect: (selection: FlowSelection | null) => void
  fitSignal: string
  theme: 'light' | 'dark'
}) {
  const rf = useReactFlow()
  const initialized = useNodesInitialized()

  useEffect(() => {
    if (initialized) rf.fitView({ padding: 0.2 })
  }, [initialized, fitSignal, rf])

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      nodeTypes={NODE_TYPES}
      colorMode={theme}
      minZoom={0.3}
      proOptions={{ hideAttribution: true }}
      onNodeClick={(_, node) => {
        if (node.type === 'integration') onSelect(node.id)
        if (node.type === 'topic') {
          const d = node.data as TopicNodeData
          if (d.pubsub) onInspect({ kind: 'topic', pubsub: d.pubsub, topic: d.name })
        }
        if (node.type === 'external') {
          const d = node.data as ExtNodeData
          if (d.connector) onInspect({ kind: 'connector', name: d.connector })
        }
      }}
      onPaneClick={() => onInspect(null)}
    >
      <Background gap={20} />
      <Controls showInteractive={false} />
      <MiniMap pannable zoomable />
    </ReactFlow>
  )
}


// refName extracts the display name from an entity ref: "component:pim-extractor"
// → "pim-extractor", "system:default/pim" → "pim".
function refName(ref: string): string {
  const rest = ref.slice(ref.indexOf(':') + 1)
  const slash = rest.lastIndexOf('/')
  return slash >= 0 ? rest.slice(slash + 1) : rest
}

// buildDeclaredGraph renders a system's declared topology (v1): components and
// the topics they publish/subscribe laid out left-to-right by flow depth
// inside the boundary, external systems (via connectors) outside it. Nothing
// here is inferred — every node and edge comes straight from the record's
// inline wiring.
function buildDeclaredGraph(
  topo: Topology,
  items: IntegrationDetail[],
): { nodes: Node[]; edges: Edge[] } {
  const comps = topo.components ?? []

  // Metadata lookups: topics carry the contract, connectors the transport and
  // external system a component's inline reference resolves against.
  const topicMeta = new Map(
    (topo.topics ?? []).map((t) => [`${t.pubsub}/${t.topic}`, t]),
  )
  const connMeta = new Map((topo.connectors ?? []).map((c) => [c.name, c]))

  // A topic node is identified by its (pubsub, topic) pair; a component by ref.
  const topicId = (pubsub: string, topic: string): string => `topic:${pubsub}/${topic}`

  // Map component refs to integration paths (a component's directory is its
  // name relative to the system root) so clicking a declared node selects the
  // scaffolded integration when one exists.
  const joinProject = (base: string, project: string): string => {
    if (project === '.' || project === '') return base
    return base === '.' ? project : `${base}/${project}`
  }
  const nodeId = new Map<string, string>()
  for (const c of comps) {
    const path = joinProject(topo.path, c.name)
    const matched = items.some((it) => it.path === path) ? path : undefined
    nodeId.set(`component:${c.name}`, matched ?? `component:${c.name}`)
  }

  // Collect the unique topics the components reference, and the internal flow
  // edges (component ⇄ topic) that decide layout depth.
  const topicRefs = new Map<string, { pubsub: string; topic: string }>()
  const flowEdges: Array<{ from: string; to: string }> = []
  for (const c of comps) {
    const cref = `component:${c.name}`
    for (const p of c.publishes ?? []) {
      const tid = topicId(p.pubsub, p.topic)
      topicRefs.set(tid, { pubsub: p.pubsub, topic: p.topic })
      flowEdges.push({ from: cref, to: tid })
    }
    for (const s of c.subscribes ?? []) {
      const tid = topicId(s.pubsub, s.topic)
      topicRefs.set(tid, { pubsub: s.pubsub, topic: s.topic })
      flowEdges.push({ from: tid, to: cref })
    }
  }
  for (const tid of topicRefs.keys()) nodeId.set(tid, tid)

  // Longest-path layering over the internal flow edges decides each node's
  // column. Kahn-style relaxation; anything left by a cycle lands in column 0
  // rather than failing the render.
  const internal = new Set<string>([
    ...comps.map((c) => `component:${c.name}`),
    ...topicRefs.keys(),
  ])
  const succ = new Map<string, string[]>()
  const indeg = new Map<string, number>()
  for (const r of internal) {
    succ.set(r, [])
    indeg.set(r, 0)
  }
  for (const e of flowEdges) {
    if (!internal.has(e.from) || !internal.has(e.to)) continue
    succ.get(e.from)?.push(e.to)
    indeg.set(e.to, (indeg.get(e.to) ?? 0) + 1)
  }
  const depth = new Map<string, number>()
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + cols * NODE_W + (cols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'
  const rowsInCol: number[] = new Array<number>(cols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    return { x: colX(d), y: contentTop + row * (NODE_H + ROW_GAP), row }
  }

  // Component positions, keyed by ref, so externals can anchor to the
  // component they touch instead of the far edge of the canvas.
  const compPos = new Map<string, { x: number; y: number; col: number }>()
  for (const c of comps) {
    const ref = `component:${c.name}`
    const col = depth.get(ref) ?? 0
    const pos = place(col)
    compPos.set(ref, { x: pos.x, y: pos.y, col })
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.kind,
        dataFlow: dataFlowFor(c.kind),
        selected: false,
      } satisfies IntNodeData,
    })
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const meta = topicMeta.get(`${ref.pubsub}/${ref.topic}`)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: meta?.contract,
      } satisfies TopicNodeData,
    })
  }

  const maxRows = Math.max(1, ...rowsInCol)
  const groupHeight = contentTop + maxRows * (NODE_H + ROW_GAP) - ROW_GAP + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system, count: comps.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Topic publish/subscribe edges. A publish leaves the component's right
  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')
  // handle for the subscriber.
  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    for (const p of c.publishes ?? []) {
      const target = nodeId.get(topicId(p.pubsub, p.topic))
      if (!target) continue
      edges.push({
        id: `e:pub:${c.name}:${p.pubsub}/${p.topic}`,
        source: comp,
        sourceHandle: 'ext',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
    for (const s of c.subscribes ?? []) {
      const source = nodeId.get(topicId(s.pubsub, s.topic))
      if (!source) continue
      edges.push({
        id: `e:sub:${s.pubsub}/${s.topic}:${c.name}`,
        source,
        sourceHandle: 'out',
        target: comp,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
  }

  // Externals sit outside the boundary, anchored to the component they touch
  // so edges stay short: an input connector directly left of its component,
  // an output connector dropped below the component's column (stacked when
  // several share one). This avoids the whole-diagram crossings that a fixed
  // left/right screen edge produces in a multi-column pipeline.
  const belowCount = new Map<number, number>()
  const belowY = (col: number): number => {
    const n = belowCount.get(col) ?? 0
    belowCount.set(col, n + 1)
    return groupHeight + EXT_VGAP + n * (EXT_H + EXT_VGAP)
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }
  const centerUnder = (x: number) => x + (NODE_W - EXT_W) / 2

  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    const anchor = compPos.get(cref)!
    for (const use of c.connectors ?? []) {
      const conn = connMeta.get(use.connector)
      const isInput = use.direction === 'in'
      const extId = `ext:${use.connector}`
      const data: ExtNodeData = {
        name: conn?.externalSystem ? refName(conn.externalSystem) : use.connector,
        type: conn?.transport.type ?? 'connector',
        direction: isInput ? 'input' : undefined,
        connector: use.connector,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id: `e:conn:${c.name}:${use.connector}`,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, centerUnder(anchor.x), belowY(anchor.col))
        edges.push({
          id: `e:conn:${c.name}:${use.connector}`,
          source: comp,
          sourceHandle: 'infra',
          target: extId,
          targetHandle: 'top',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
    }
  }

  return { nodes, edges }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, dataFlow, selected, trigger } = data as IntNodeData
  const Icon = dataFlow ? DATA_FLOW_ICONS[dataFlow] : MemoryIcon
  return (
    <div className={`rf-int${selected ? ' selected' : ''}`}>
      <div className="rf-int-head">
        <Icon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
        {trigger && (
          <span className="rf-int-tag" title="schedule trigger">
            {trigger}
          </span>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// TopicNode is a declared pub/sub topic: the first-class hop between
// components a declared topology makes visible. Contract topics show their
// contract ref; internal ones their data entity.
function TopicNode({ data }: NodeProps) {
  const { name, entity, contract } = data as TopicNodeData
  // Topic names share a long common prefix, so lead with the short entity and
  // keep the full topic/contract in a tooltip. Fall back to the name when a
  // topic declares no entity.
  const primary = entity ?? name
  const secondary = contract ?? name
  const tip = contract ? `${name}\n${contract}` : name
  return (
    <div className="rf-infra pubsub" title={tip}>
      <Handle type="target" position={Position.Left} id="in" />
      <HubIcon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{primary}</span>
        <span className="rf-infra-kind">{secondary}</span>
      </div>
      <Handle type="source" position={Position.Right} id="out" />
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type, direction } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  const kind = direction === 'input' ? 'source' : isDisk ? 'disk' : 'external'
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="target" position={Position.Top} id="top" />
      <Handle type="source" position={Position.Right} id="out" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

const NODE_TYPES = {
  group: GroupNode,
  integration: IntegrationNode,
  external: ExternalNode,
  topic: TopicNode,
}

// Types mirror the Go JSON contract served by `intropy dashboard`
// (internal/dashboard). Integration matches template.ScaffoldEntry;
// IntegrationDetail adds the best-effort on-disk enrichment.

/** A dependency another template rendered alongside this integration. */
export interface DependencyRecord {
  template: string
  /** Slash-separated directory relative to the component root. */
  dir: string
}

export interface Integration {
  path: string
  schemaVersion: number
  template: string
  owner: string
  repo: string
  version: string
  /** Which way data crosses the system boundary, declared by the template
   *  (intropy.dev/data-flow label) and recorded in scaffold.json. */
  dataFlow?: 'in' | 'out' | 'both' | 'internal'
  /** Topology block kind the template scaffolds (intropy.dev/block-kind
   *  label), e.g. "extractor" or "loader". */
  blockKind?: string
  /** Support-project role (intropy.dev/template-role label). Projects with a
   *  role (system-host, shared-library) are filtered out of the catalog by
   *  the server; the field only appears on records read elsewhere. */
  role?: string
  /** Sibling projects this integration's template rendered as dependencies. */
  dependsOn?: DependencyRecord[]
  values: Record<string, unknown>
  /** Directory carrying the .intropy record; the integration's display name. */
  name: string
  /** Parent directory of the integration; absent directly under the root. */
  system?: string
  /** Parent directory of the system; absent when the system sits at the root. */
  domain?: string
}

export interface FileDoc {
  name: string
  content: string
}

/** A parsed Dapr component. `category` decides where the flow canvas draws it:
 *  `pubsub`/`state` inside the system boundary, `binding` outside — as a
 *  source when `direction` is `input`, a sink otherwise. */
export interface DaprComponent {
  name: string
  type: string
  category: 'pubsub' | 'state' | 'binding' | 'other'
  /** Normalized `direction` metadata from the component spec. Absent when
   *  undeclared — treated as unknown (rendered as a sink), never inferred. */
  direction?: 'input' | 'output' | 'input,output'
  file: string
}

export interface IntegrationDetail extends Integration {
  agents?: FileDoc
  readme?: FileDoc
  components?: DaprComponent[]
  pipelineSteps?: string[]
}

export interface Health {
  status: string
  version: string
}

// Deployment state (internal/deploy). The server obtains each record by running
// the `deploy status` command with a JSON writer and passing its result through
// unchanged, so everything below is that command's own output — including the
// prose in `summary` and `notes`, which must be rendered as served rather than
// re-derived from `environments`.

/** How one overlay pins one image. */
export interface ResultPin {
  image: string
  /** The digest this replaced. Only present on a deployment's own result. */
  previous?: string
  digest: string
  /** The tag the digest was resolved from, or the tag pinned instead of a
   *  digest. Empty when the digest came from a release manifest. */
  tag?: string
}

/** One environment's row of the deployment ladder. */
export interface EnvironmentStatus {
  environment: string
  appName: string
  overlayPath: string
  /** False means there is no readable overlay here; `reason` says why and
   *  everything below is empty. On its own it never means "not deployed". */
  onboarded: boolean
  reason?: string
  /** The version this environment runs. Absent when it was deployed from a
   *  commit rather than a release, in which case `sourceCommit` stands in. */
  release?: string
  sourceCommit?: string
  /** Every image the component declares, in declared order. `digest` is empty
   *  when the overlay pins a tag or nothing — `tag` says which. */
  pins?: ResultPin[]
  /** The GitOps commit that last changed this overlay, and when it landed.
   *  Both absent when the overlay path has no history. */
  revision?: string
  /** RFC 3339. */
  deployedAt?: string
  syncPolicy: 'auto' | 'manual' | string
  /** What ArgoCD reports. Absent when it could not be read — which says
   *  nothing at all about what the overlay pins. */
  syncStatus?: string
  healthStatus?: string
  syncedRevision?: string
  /** A committed overlay change ArgoCD has not applied. For a `manual`
   *  environment that is an unspent gate at rest, not a fault. */
  pending: boolean
}

export interface StatusResult {
  component: string
  domain: string
  system: string
  /** Declared kind. "shared" holds system-level manifests and no image, so its
   *  empty digests are by design rather than evidence of never deploying. */
  kind: 'service' | 'shared' | string
  /** In promotion order: the last entry is the furthest downstream. */
  environments: EnvironmentStatus[]
  /** Every onboarded environment pins the identical digest for every image —
   *  what makes "prod runs the bits staging tested" a fact. */
  consistent: boolean
  /** The command's own sentence about what the environments collectively run.
   *  Render as served: `consistent` is a bool and the interesting cases are
   *  not — "these run different bits" and "there is nothing to compare" are
   *  both false and mean very different things. */
  summary: string
  /** The command's qualifications: an environment that could not be read, one
   *  pinning a tag, one waiting on a sync gate. */
  notes?: string[]
}

/** The /api/deploy/{path} payload: what the deploy status command said about one
 *  integration, or why it could not say anything. */
export interface DeployState {
  status?: StatusResult
  /** The command's message, verbatim — an unconfigured GitOps repository, a
   *  component name matching several, a checkout another deploy is holding.
   *  None of these is a statement about the integration; only `status` is. */
  error?: string
  /** What the command wrote to stderr: which repository it refreshed, and any
   *  environment ArgoCD could not be read for. Provenance, not failure. */
  diagnostics?: string[]
  /** RFC 3339 — when the command ran. */
  readAt: string
}

// Declared system topology (internal/topology). The server obtains each
// record by running the system host's `graph` verb (apiVersion
// topology.intropy.io/v1) and caches the result until an explicit refresh.
// Wiring is inlined on each component — the topics it subscribes to and
// publishes on and the connectors it uses — while the top-level `topics` and
// `connectors` sections are the lookup tables those inline references resolve
// against. There is no fallback: a system whose host cannot produce a record
// appears in `errors` instead of `topologies`.

/** A component's subscription to a pub/sub topic. */
export interface TopicRef {
  pubsub: string
  topic: string
}

/** A component's output onto a pub/sub topic. */
export interface Publication {
  /** Component output port the message leaves through. */
  port?: string
  pubsub: string
  topic: string
}

/** A component's use of an external connector. */
export interface ConnectorUse {
  connector: string
  /** "in" (external → component) or "out" (component → external). */
  direction: 'in' | 'out'
}

export interface TopologyComponent {
  name: string
  /** Block type: extractor, loader, transactionalIntegration, … */
  kind: string
  subscribes?: TopicRef[]
  publishes?: Publication[]
  connectors?: ConnectorUse[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  provides?: unknown[]
  consumes?: unknown[]
}

/** A declared pub/sub topic: metadata for a (pubsub, topic) pair components
 *  reference. */
export interface TopologyTopic {
  pubsub: string
  topic: string
  contract?: string
  publishers?: string[]
  subscribers?: string[]
}

export interface TopologyTransport {
  type: string
  supportsInput: boolean
  supportsOutput: boolean
}

/** An external system integration point. */
export interface TopologyConnector {
  name: string
  externalSystem?: string
  transport: TopologyTransport
  directions?: Array<'in' | 'out'>
  usedBy?: string[]
}

/** A message contract in the system's registry, keyed by `name` — the same
 *  fully-qualified type name TopologyTopic.contract references. */
export interface Contract {
  name: string
  /** "event" for pub/sub message contracts. */
  kind?: string
  /** Bare type name — the join key to a scaffold record's values.contract. */
  shortName?: string
  mediaType?: string
  /** Hash of the schema's canonical form; equal fingerprints mean equal
   *  shapes across systems. */
  fingerprint?: string
  /** JSON Schema as the host emitted it, passed through verbatim. */
  schema?: JsonSchema
}

/** The subset of JSON Schema the contract field tree renders. Anything it
 *  does not recognize falls back to a raw type label, never an error. */
export interface JsonSchema {
  type?: string | string[]
  format?: string
  properties?: Record<string, JsonSchema>
  required?: string[]
  items?: JsonSchema
  enum?: unknown[]
  $ref?: string
  $defs?: Record<string, JsonSchema>
}

/** One field or column of an external payload, as its author described it.
 *  `type` is loose by design — documentation, not a validatable schema. */
export interface MessageDocField {
  name: string
  position?: number
  type?: string
  required?: boolean
  notes?: string
}

/** A short inline payload excerpt. The server only serves samples whose
 *  author explicitly asserted the redaction check. */
export interface MessageDocSample {
  inline: string
  redacted?: boolean
}

/** An authored description of the payload a connector carries (the flat file
 *  from an SFTP drop, the ad-hoc CSV export), read from the system's
 *  messages/<connector>.md sidecar. Documentation, not enforcement. */
export interface MessageDoc {
  format?: string
  delimiter?: string
  encoding?: string
  filePattern?: string
  frequency?: string
  contact?: string
  lastReviewed?: string
  fields?: MessageDocField[]
  sample?: MessageDocSample
  /** Free prose from the doc's Markdown body. */
  body?: string
}

export interface Topology {
  /** Root-relative system directory, same identifier space as Integration.path. */
  path: string
  apiVersion: string
  kind?: string
  /** System name (a bare string in v1). */
  system: string
  components?: TopologyComponent[]
  topics?: TopologyTopic[]
  connectors?: TopologyConnector[]
  /** Message contract registry topics reference by contract name. Absent
   *  until the system host's topology library emits it. */
  contracts?: Contract[]
  /** Contract surfaces — parsed but not yet rendered (shape not finalized). */
  apis?: unknown[]
  /** Authored connector payload descriptions, keyed by connector name.
   *  CLI-merged enrichment from messages/<connector>.md — not part of the
   *  host-declared topology, and re-read on every request. */
  messageDocs?: Record<string, MessageDoc>
}

/** The /api/topology payload: every declared topology plus the per-host
 *  failures (a host whose graph verb failed, e.g. because it pre-dates the
 *  verb or does not build). */
export interface TopologyReport {
  topologies: Topology[]
  errors?: string[]
}

async function requestJSON<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, init)
  if (!res.ok) {
    let message = `${res.status} ${res.statusText}`
    try {
      const body = (await res.json()) as { error?: string }
      if (body?.error) message = body.error
    } catch {
      // response had no JSON error body; keep the status line
    }
    throw new Error(message)
  }
  return (await res.json()) as T
}

const getJSON = <T,>(url: string) => requestJSON<T>(url)

export const api = {
  listIntegrations: () => getJSON<Integration[]>('/api/integrations'),
  getIntegration: (path: string) =>
    getJSON<IntegrationDetail>(`/api/integrations/${path}`),
  /** Every integration enriched with pipeline steps + Dapr components for the flow canvas. */
  flow: () => getJSON<IntegrationDetail[]>('/api/flow'),
  /** Every declared system topology, cached from the hosts' graph verbs. */
  topologies: () => getJSON<TopologyReport>('/api/topology'),
  /** Re-run every host's graph verb and return the fresh report. */
  refreshTopologies: () =>
    requestJSON<TopologyReport>('/api/topology/refresh', { method: 'POST' }),
  /** One integration's deployment state, read once and reused by the server. */
  deployState: (path: string) => getJSON<DeployState>(`/api/deploy/${path}`),
  /** Re-run `deploy status` for one integration and return the fresh result —
   *  how you pick up a deploy just made from another terminal. */
  refreshDeployState: (path: string) =>
    requestJSON<DeployState>(`/api/deploy/${path}`, { method: 'POST' }),
  health: () => getJSON<Health>('/api/health'),

  // Template endpoints (internal/dashboard/templates.go). They wrap the
  // `template` and `int create` commands: the library release the server
  // fetched is the release the form renders against and the run creates from.
  listTemplates: () => getJSON<TemplateList>('/api/templates'),
  getTemplate: (name: string) => getJSON<TemplateDetail>(`/api/templates/${name}`),
  /** Render a template into the workspace — the Run button's `int create`. */
  createTemplate: (name: string, req: CreateRequest) =>
    requestJSON<CreateResponse>(`/api/templates/${name}/create`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(req),
    }),
}

// Template API (internal/dashboard/templates.go). The shapes mirror the Go
// JSON contract the endpoints serve: template.List, template.DescribeResult
// (plus the ordered `fields` JSON round-tripping would lose), and
// template.CreateResult.

/** The /api/templates payload: one library release's template names. */
export interface TemplateList {
  owner: string
  repo: string
  version: string
  templates: string[]
}

/** One parameter of a template's schema, in YAML declaration order. Mirrors
 *  template.FieldSpec — the form renders from these, never the raw schema. */
export interface TemplateField {
  name: string
  title?: string
  description?: string
  type: 'string' | 'boolean' | 'integer' | 'number'
  enum?: unknown[]
  default?: unknown
  pattern?: string
  required: boolean
}

/** The /api/templates/{name} payload: `template show -o json` plus the
 *  declaration-ordered field list. `parameters` is the raw JSON Schema. */
export interface TemplateDetail {
  template: string
  title?: string
  description?: string
  tags?: string[]
  labels?: Record<string, string>
  owner: string
  repo: string
  version: string
  parameters: Record<string, unknown>
  dependencies?: { template: string; output: string }[]
  fields: TemplateField[]
}

/** The POST body for create. `name` folds into values.name and becomes the
 *  output directory under the workspace root, as `int create --name` does. */
export interface CreateRequest {
  name: string
  values: Record<string, unknown>
  force?: boolean
}

/** The 201 payload: template.CreateResult with a root-relative outputDir. */
export interface CreateResponse {
  template: string
  owner: string
  repo: string
  version: string
  outputDir: string
  values: Record<string, unknown>
  dependencies?: { template: string; outputDir: string; action: string }[]
  diagnostics?: string[]
}

// Package dashboard serves the local Intropy integration dashboard: a small
// stdlib net/http server that exposes a read-only JSON API over the
// integrations discovered under a workspace root and serves the embedded SPA
// that renders them.
//
// It starts no integration processes and changes nothing. What it does run is
// two things, both on request rather than at startup: each system host's `graph`
// verb, for the topology the flow view draws, and the deploy status command, for
// what the catalog reports each environment is running. The second one refreshes
// the cached GitOps checkout and reads ArgoCD, so it is the only part of this
// package that touches the network — asked for one integration at a time, and
// reused until an explicit refresh.
//
// Deployment facts are never derived here. The command owns every refusal that
// matters — an unset gitopsRepo, a component name matching several, an
// environment nobody has onboarded — and its answers are passed through
// verbatim, so the dashboard cannot claim something the command line would not.
package dashboard

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

// Options configures a dashboard server. The zero value is not usable; Root is
// required and Addr/Port select the listen address.
type Options struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Addr is the host/interface to bind, e.g. "127.0.0.1". Empty binds all.
	Addr string
	// Port is the TCP port to bind. 0 asks the OS for a free port.
	Port int
	// OpenBrowser opens the dashboard URL in the default browser on start.
	OpenBrowser bool
	// Version is reported by GET /api/health.
	Version string
	// TemplateVersion pins the template library release the /api/templates
	// endpoints fetch and render against. Empty resolves the latest release.
	TemplateVersion string
	// Stdout and Stderr receive program output and diagnostics; both default
	// to the process streams when nil.
	Stdout io.Writer
	Stderr io.Writer
}

// shutdownTimeout bounds how long in-flight requests have to drain on Ctrl+C.
const shutdownTimeout = 5 * time.Second

// Serve starts the dashboard and blocks until ctx is cancelled (e.g. SIGINT)
// or the server fails. On cancellation it shuts down gracefully and returns
// nil; it returns a non-nil error only for a real startup or runtime failure.
func Serve(ctx context.Context, opts Options) error {
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	root := opts.Root
	if root == "" {
		root = "."
	}
	// Resolve to an absolute path: the API mixes root-relative identifiers
	// with absolute on-disk results (a create's outputDir), and relPath can
	// only join the two when root itself is absolute.
	if abs, err := filepath.Abs(root); err == nil {
		root = abs
	}

	handler, err := newHandler(root, opts.Version, providers{
		topology: hostGraphProvider(root),
		deploy:   statusCommandProvider(opts.Version),
		templates: templatesProvider{
			version:   opts.TemplateVersion,
			userAgent: "intropy-cli/" + opts.Version,
		},
	})
	if err != nil {
		return fmt.Errorf("run: %w", err)
	}

	addr := net.JoinHostPort(opts.Addr, fmt.Sprintf("%d", opts.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("run: cannot listen on %s: %w", addr, err)
	}

	url := displayURL(opts.Addr, ln.Addr())
	fmt.Fprintf(opts.Stderr, "Intropy dashboard running at %s\n", url)
	fmt.Fprintln(opts.Stderr, "Press Ctrl+C to stop.")

	if opts.OpenBrowser {
		if err := openBrowser(url); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not open browser: %v\n", err)
		}
	}

	srv := &http.Server{Handler: handler}
	errCh := make(chan error, 1)
	go func() {
		err := srv.Serve(ln)
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	select {
	case <-ctx.Done():
		fmt.Fprintln(opts.Stderr, "\nShutting down…")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			return fmt.Errorf("run: shutdown: %w", err)
		}
		return nil
	case err := <-errCh:
		if err != nil {
			return fmt.Errorf("run: server error: %w", err)
		}
		return nil
	}
}

// displayURL builds a browser-friendly URL. It uses the actual bound port
// (important when Port was 0) and rewrites wildcard bind hosts to localhost.
func displayURL(host string, addr net.Addr) string {
	port := 0
	if tcp, ok := addr.(*net.TCPAddr); ok {
		port = tcp.Port
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "localhost"
	}
	return fmt.Sprintf("http://%s", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
}

// Package topology models the declared system topology an integration
// system's host emits. The record declares the system's shape: its components
// (blocks) and the wiring between them, expressed inline on each component —
// the topics it subscribes to and publishes on, the API contracts it provides
// and consumes, and the external connectors it uses. Top-level topics[] and
// connectors[] sections carry the shared metadata (contracts, transports,
// external systems) those inline references point at.
//
// The CLI never derives a topology itself: the system host's `graph` verb
// prints the record — JSON only, on stdout — and consumers decode that stream.
package topology

import (
	"encoding/json"
	"fmt"
	"io"
)

const (
	// APIVersion is the topology schema this CLI understands. A record with
	// any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the connectors it uses. The top-level
// Topics and Connectors sections are lookup tables the inline references
// resolve against (contract, transport, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Connectors []Connector `json:"connectors,omitempty"`
	Contracts  []Contract  `json:"contracts,omitempty"`
	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
}

// Component is a deployable block of the system. Kind is the block type
// (extractor, loader, transactionalIntegration, …). A component's directory,
// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string         `json:"name"`
	Kind       string         `json:"kind"`
	Subscribes []TopicRef     `json:"subscribes,omitempty"`
	Publishes  []Publication  `json:"publishes,omitempty"`
	Connectors []ConnectorUse `json:"connectors,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic. Port names the
// component output the message leaves through.
type Publication struct {
	Port   string `json:"port,omitempty"`
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// ConnectorUse is a component's use of an external connector. Direction is
// "in" (external → component) or "out" (component → external).
type ConnectorUse struct {
	Connector string `json:"connector"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Contract is a message contract in the system's registry, keyed by Name —
// the same fully-qualified type name Topic.Contract references. ShortName is
// the bare type name (the join key to a scaffold record's values.contract).
// Schema is the contract's JSON Schema as the host emitted it; the CLI passes
// it through to the frontend without interpreting it. Fingerprint identifies
// the schema shape (a hash over its canonical form), so equal fingerprints
// mean equal shapes across systems.
type Contract struct {
	Name        string          `json:"name"`
	Kind        string          `json:"kind,omitempty"`
	ShortName   string          `json:"shortName,omitempty"`
	MediaType   string          `json:"mediaType,omitempty"`
	Fingerprint string          `json:"fingerprint,omitempty"`
	Schema      json.RawMessage `json:"schema,omitempty"`
}

// Transport describes how a connector moves data. SupportsInput/SupportsOutput
// declare the directions the transport itself can carry.
type Transport struct {
	Type           string `json:"type"`
	SupportsInput  bool   `json:"supportsInput"`
	SupportsOutput bool   `json:"supportsOutput"`
}

// Connector is an external system integration point. ExternalSystem is the
// system it fronts, Directions the directions it is wired in, and UsedBy the
// components that use it.
//
// Transport is the connector's local materialization (what F5 runs use).
// DeployedTransport, when the host declares one, is the value-free transport
// shape the connector materializes as after deployment; it is nil for hosts
// that predate the field or whose local transport also applies to deployed
// environments. Connection values never appear here — they are placeholders in
// the rendered GitOps overlays.
type Connector struct {
	Name              string     `json:"name"`
	ExternalSystem    string     `json:"externalSystem,omitempty"`
	Transport         Transport  `json:"transport"`
	DeployedTransport *Transport `json:"deployedTransport,omitempty"`
	Directions        []string   `json:"directions,omitempty"`
	UsedBy            []string   `json:"usedBy,omitempty"`
}

// Entry is one system's topology plus the workspace directory it belongs to,
// flattened into one self-describing JSON document for the API.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// Decode parses a topology record from r (typically a host `graph` verb's
// stdout). A record whose apiVersion this CLI does not understand is an
// error, not a guess. Callers wrap the error with the record's origin.
func Decode(r io.Reader) (*Topology, error) {
	var t Topology
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("parse topology record: %w", err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("unsupported topology apiVersion %q (this CLI understands %q)",
			t.APIVersion, APIVersion)
	}
	return &t, nil
}

package dashboard

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
// the detail endpoint returns, so a huge file cannot bloat a response.
const maxDocBytes = 128 * 1024

// providers are the request-independent sources the API reads beyond the
// workspace's own files: what a system host declares about its topology, and
// what the GitOps repository says is deployed. Both run a command, so both are
// injected as function values that tests replace. templates is a value, not a
// function: it carries configuration (release pin, test overrides), not a
// stubbed behavior — tests override its fields instead.
type providers struct {
	topology  topologyProvider
	deploy    deployProvider
	templates templatesProvider
}

// deployStateTimeout bounds one deploy status run.
//
// It exists for the checkout lock rather than for the browser: the command holds
// an exclusive lock on the shared GitOps checkout for its whole duration, and an
// ArgoCD server that accepts connections but never answers would otherwise keep
// that lock — blocking the user's own intropy deploy indefinitely. A minute is
// generous for a fetch plus a handful of ArgoCD calls and short enough that a
// hung one lets go.
const deployStateTimeout = time.Minute

// apiServer holds the request-independent state for the JSON API.
type apiServer struct {
	root      string
	version   string
	topo      topologyProvider
	dep       deployProvider
	templates templatesProvider

	// createMu serializes template create runs: two concurrent renders of the
	// same name would race on the output directory, and each run downloads a
	// library tarball. The same bargain depMu makes for the shared checkout.
	createMu sync.Mutex

	// topoMu guards the cached provider result. Fetching runs the hosts'
	// graph verbs (a dotnet build on first run), so the result is computed
	// once — on the first /api/topology request — and reused until an
	// explicit refresh.
	topoMu      sync.Mutex
	topoLoaded  bool
	topoEntries []topology.Entry
	topoErrs    []string

	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState
}

// topologyReport is the /api/topology payload: every declared topology plus
// the per-host failures the UI renders. Topologies is always an array (never
// null) even when empty.
type topologyReport struct {
	Topologies []topologyEntry `json:"topologies"`
	Errors     []string        `json:"errors,omitempty"`
}

// topologyEntry is one system's declared topology plus the authored
// enrichment read from its directory: message descriptions keyed by connector
// name. The docs ride beside the Topology rather than inside it — the
// topology stays exactly what the host declared.
type topologyEntry struct {
	topology.Entry
	MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
}

// fileDoc is a text document surfaced in an integration's detail view.
type fileDoc struct {
	Name    string `json:"name"`
	Content string `json:"content"`
}

// integrationSummary is a scaffold entry plus the coordinates the sidebar
// tree groups by: Name is the directory that carries the .intropy record.
// System is the name a sibling system-host scaffold declares for the
// directory's parent, falling back to the parent folder's name; Domain is the
// system's parent folder. Absent a host, System is empty when the integration
// sits directly under the workspace root, and Domain is empty when the
// system does.
type integrationSummary struct {
	template.ScaffoldEntry
	Name   string `json:"name"`
	System string `json:"system,omitempty"`
	Domain string `json:"domain,omitempty"`
}

// integrationDetail is a single integration plus best-effort, on-disk
// enrichment. Every enrichment field is optional and absent when the
// corresponding file or directory does not exist.
type integrationDetail struct {
	integrationSummary
	Agents        *fileDoc        `json:"agents,omitempty"`
	Readme        *fileDoc        `json:"readme,omitempty"`
	Components    []DaprComponent `json:"components,omitempty"`
	PipelineSteps []string        `json:"pipelineSteps,omitempty"`
}

// newHandler wires the API routes and the SPA static handler onto a mux.
func newHandler(root, version string, p providers) (http.Handler, error) {
	api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy, templates: p.templates}
	static, err := staticHandler()
	if err != nil {
		return nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", api.health)
	mux.HandleFunc("GET /api/integrations", api.listIntegrations)
	mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
	mux.HandleFunc("GET /api/flow", api.flow)
	mux.HandleFunc("GET /api/topology", api.topologies)
	mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
	// The verb carries the meaning rather than a /refresh segment: a {path...}
	// wildcard has to be the last thing in the pattern. GET serves what has
	// already been read, POST runs the command again.
	mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
	mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
	// Template endpoints follow the same GET-read / POST-act split: list and
	// show fetch the library release, create renders into the workspace.
	mux.HandleFunc("GET /api/templates", api.listTemplates)
	mux.HandleFunc("GET /api/templates/{name}", api.getTemplate)
	mux.HandleFunc("POST /api/templates/{name}/create", api.createTemplate)
	mux.Handle("/", static)
	return mux, nil
}

func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status":  "ok",
		"version": s.version,
	})
}

// listIntegrations mirrors `int list -o json` — the same scaffold entries in
// the same order — with the derived name/system fields added on top and each
// Path normalized to a root-relative identifier. The response is always an
// array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, s.summarize(e, systems))
	}
	writeJSON(w, http.StatusOK, summaries)
}

// scan splits the workspace's scaffold entries for the API: the integration
// blocks to catalog, plus the declared systems keyed by their root directory
// (the directory holding a system-host scaffold). Support projects — the host
// and its shared contracts library — are infrastructure the system view
// already represents, not integrations to list.
func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
	entries, _ := template.ListScaffolds(s.root)
	systems = map[string]string{}
	for _, e := range entries {
		if e.Role == template.RoleSystemHost {
			systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
		}
	}
	blocks = entries[:0]
	for _, e := range entries {
		if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
			continue
		}
		blocks = append(blocks, e)
	}
	return blocks, systems
}

// systemName is the name a system-host scaffold declares for its system
// (the template's `name` value, recorded at `sys create`), falling back to
// the host's parent directory name.
func systemName(host template.ScaffoldEntry) string {
	if name, ok := host.Values["name"].(string); ok && name != "" {
		return name
	}
	dir := filepath.Dir(host.Path)
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// summarize derives an entry's tree coordinates from its path and the
// declared systems. A sibling system-host makes membership explicit: its
// declared name wins over the folder-derived one and applies even directly
// under the workspace root (where no folder-derived system exists).
// Otherwise the workspace root itself never counts as a system or domain, so
// an integration scaffolded at the root has neither and one directly under
// the root has a system but no domain. The served Path is made root-relative
// so it is a stable, URL-safe identifier regardless of whether the command
// was given a relative or absolute root (an absolute path would otherwise
// break detail lookups).
func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
	sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
	sum.Path = s.relPath(e.Path)
	path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
	parent := filepath.Dir(path)
	if declared, ok := systems[parent]; ok && path != root {
		sum.System = declared
		if grand := filepath.Dir(parent); parent != root && grand != root {
			sum.Domain = filepath.Base(grand)
		}
		return sum
	}
	if path == root || parent == root {
		return sum
	}
	sum.System = filepath.Base(parent)
	if grand := filepath.Dir(parent); grand != root {
		sum.Domain = filepath.Base(grand)
	}
	return sum
}

// relPath turns an entry's on-disk path into the root-relative, slash-separated
// identifier used in API responses and URLs. It falls back to the cleaned path
// so a value is always produced even if Rel fails (e.g. differing volumes).
func (s *apiServer) relPath(p string) string {
	if rel, err := filepath.Rel(s.root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

// flow returns every integration enriched with the pipeline steps and Dapr
// components the flow canvas draws, so the whole graph loads in one request.
// It reuses integrationDetail but leaves the document fields (agents/readme)
// nil — the canvas nodes do not render them.
func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	nodes := make([]integrationDetail, 0, len(entries))
	for _, e := range entries {
		dir := e.Path
		nodes = append(nodes, integrationDetail{
			integrationSummary: s.summarize(e, systems),
			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
		})
	}
	writeJSON(w, http.StatusOK, nodes)
}

// topologies returns every system topology declared by a host's graph verb,
// each Path normalized to the same root-relative identifier integration
// paths use, so the flow canvas can match a topology to the integrations
// living beside its host. The provider result is cached after the first
// request (the verb builds the host); POST /api/topology/refresh recomputes.
func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
}

// refreshTopologies recomputes the topology cache by re-running every host's
// graph verb, then returns the fresh report.
func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
}

// topologyReport assembles the /api/topology payload: the cached provider
// result plus the message docs read fresh from disk on every request, so an
// edited doc shows up on a browser refresh without re-running the hosts'
// graph verbs.
func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
	entries, errs := s.cachedTopologies(ctx, force)
	report := topologyReport{
		Topologies: make([]topologyEntry, 0, len(entries)),
		Errors:     append([]string(nil), errs...),
	}
	for _, e := range entries {
		docs, docErrs := s.messageDocs(e)
		report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
		report.Errors = append(report.Errors, docErrs...)
	}
	return report
}

// cachedTopologies returns the provider result — computed on first use or
// when force is set, reused otherwise. Concurrent requests share one
// computation. Entry paths are normalized to root-relative identifiers.
func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	if !s.topoLoaded || force {
		entries, errs := s.topo(ctx)
		s.topoEntries = make([]topology.Entry, 0, len(entries))
		for _, e := range entries {
			e.Path = s.relPath(e.Path)
			s.topoEntries = append(s.topoEntries, e)
		}
		s.topoErrs, s.topoLoaded = errs, true
	}
	return s.topoEntries, s.topoErrs
}

// messageDocs reads the authored connector payload descriptions beside a
// system, keyed by connector name. A doc naming a connector the topology does
// not declare is surfaced as an error and withheld — never guessed around.
// Error messages carry the doc's workspace-relative path.
func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
	docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
	prefix := ""
	if e.Path != "." {
		prefix = e.Path + "/"
	}
	for i, msg := range errs {
		errs[i] = prefix + msg
	}
	known := map[string]bool{}
	for _, c := range e.Connectors {
		known[c.Name] = true
	}
	var unknown []string
	for name := range docs {
		if !known[name] {
			unknown = append(unknown, name)
			delete(docs, name)
		}
	}
	sort.Strings(unknown)
	for _, name := range unknown {
		errs = append(errs, fmt.Sprintf("%s%s/%s.md: no connector %q declared by system %q",
			prefix, messagesDirName, name, name, e.System))
	}
	if len(docs) == 0 {
		docs = nil
	}
	return docs, errs
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.enrich(e, systems)
	})
}

// getDeployState serves what the deploy status command last said about one
// integration, running it on the first request and reusing that until a POST to
// the same path. It is a separate endpoint from the integration detail because
// the two cost very different things: detail is local files, this refreshes a
// GitOps checkout over the network. Keeping them apart lets the detail panel
// render immediately and fill the deployment in when it arrives.
func (s *apiServer) getDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, false)
}

// refreshDeployState re-runs the command for one integration and returns the
// fresh result, picking up a deploy someone just made from another terminal.
func (s *apiServer) refreshDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, true)
}

func (s *apiServer) deployStateByPath(w http.ResponseWriter, r *http.Request, force bool) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.cachedDeployState(r.Context(), s.summarize(e, systems), force)
	})
}

// byPath resolves the {path...} wildcard to a scaffolded integration and serves
// what render makes of it, or 404s. Shared so the detail and deployment
// endpoints agree about which identifiers name the same integration.
func (s *apiServer) byPath(w http.ResponseWriter, r *http.Request, render func(template.ScaffoldEntry, map[string]string) any) {
	want := strings.Trim(r.PathValue("path"), "/")
	// An integration at the workspace root has the identifier "." (see
	// relPath), but a browser strips the "." segment from /api/integrations/.
	// so it arrives empty — treat the two as the same request.
	if want == "" {
		want = "."
	}
	entries, systems := s.scan()
	for _, e := range entries {
		if s.relPath(e.Path) == want {
			writeJSON(w, http.StatusOK, render(e, systems))
			return
		}
	}
	writeError(w, http.StatusNotFound, "integration not found: "+want)
}

// cachedDeployState returns one integration's deployment state — computed on
// first use or when force is set, reused otherwise.
//
// The mutex is held across the provider call rather than only around the map,
// because the command takes an exclusive lock on the shared GitOps checkout:
// two requests running it at once would have one of them fail on the other's
// lock. Serialising here turns that failure into a wait, and concurrent requests
// for the same integration share one run — the same bargain cachedTopologies
// makes with topoMu.
func (s *apiServer) cachedDeployState(ctx context.Context, sum integrationSummary, force bool) deployState {
	s.depMu.Lock()
	defer s.depMu.Unlock()

	if state, ok := s.depStates[sum.Path]; ok && !force {
		return state
	}

	ctx, cancel := context.WithTimeout(ctx, deployStateTimeout)
	defer cancel()
	state := s.dep(ctx, sum)

	if s.depStates == nil {
		s.depStates = map[string]deployState{}
	}
	s.depStates[sum.Path] = state
	return state
}

// enrich reads optional on-disk context for an integration. The entry's Path
// is already usable from the process working directory (see ListScaffolds), so
// it doubles as the project directory.
func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
	dir := e.Path
	return integrationDetail{
		integrationSummary: s.summarize(e, systems),
		Agents:             readDoc(dir, "AGENTS.md"),
		Readme:             readDoc(dir, "README.md"),
		Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
		PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
	}
}

// readDoc returns the named text file's (possibly truncated) contents, or nil
// if it is absent or unreadable.
func readDoc(dir, name string) *fileDoc {
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return nil
	}
	if len(data) > maxDocBytes {
		data = data[:maxDocBytes]
	}
	return &fileDoc{Name: name, Content: string(data)}
}

// listNames returns the sorted base names of the files directly under dir, or
// nil if dir is absent or unreadable.
func listNames(dir string) []string {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var names []string
	for _, ent := range ents {
		if !ent.IsDir() {
			names = append(names, ent.Name())
		}
	}
	sort.Strings(names)
	return names
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	_ = enc.Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

import type { ReactNode } from 'react'
import type {
  Contract,
  JsonSchema,
  MessageDoc,
  Topology,
  TopologyConnector,
  TopologyTopic,
} from '../api'
import {
  CategoryIcon,
  CloudIcon,
  DescriptionIcon,
  HubIcon,
  TuneIcon,
} from '../icons'
import { Meta, Section } from './DetailPanel'

/** What the flow canvas has put under inspection: a pub/sub topic (internal
 *  message) or a connector (external message). */
export type FlowSelection =
  | { kind: 'topic'; pubsub: string; topic: string }
  | { kind: 'connector'; name: string }

interface Props {
  selection: FlowSelection
  topology: Topology
  onClose: () => void
}

/** FlowDetail is the flow view's inspector: what message flows here, and what
 *  does it look like. Topics render their contract's field tree (when the
 *  host published a schema); connectors render the authored message doc from
 *  messages/<connector>.md (when one exists). */
export function FlowDetail({ selection, topology, onClose }: Props) {
  return (
    <aside className="flow-detail">
      <div className="flow-detail-head">
        <span className="flow-detail-title">
          {selection.kind === 'topic' ? selection.topic : selection.name}
        </span>
        <button
          type="button"
          className="flow-detail-close"
          onClick={onClose}
          aria-label="Close details"
        >
          ×
        </button>
      </div>
      {selection.kind === 'topic' ? (
        <TopicDetail selection={selection} topology={topology} />
      ) : (
        <ConnectorDetail name={selection.name} topology={topology} />
      )}
    </aside>
  )
}

function TopicDetail({
  selection,
  topology,
}: {
  selection: Extract<FlowSelection, { kind: 'topic' }>
  topology: Topology
}) {
  const topic: TopologyTopic | undefined = topology.topics?.find(
    (t) => t.pubsub === selection.pubsub && t.topic === selection.topic,
  )
  const contract: Contract | undefined = topic?.contract
    ? topology.contracts?.find((c) => c.name === topic.contract)
    : undefined

  return (
    <>
      <div className="meta-grid">
        <Meta label="Topic" value={selection.topic} />
        <Meta label="Pubsub" value={selection.pubsub} />
      </div>

      {(topic?.publishers?.length || topic?.subscribers?.length) ? (
        <Section title="Flow" icon={HubIcon}>
          <NameChips label="Publishers" names={topic?.publishers} />
          <NameChips label="Subscribers" names={topic?.subscribers} />
        </Section>
      ) : null}

      <Section title="Contract" icon={CategoryIcon}>
        {!topic?.contract ? (
          <p className="muted">This topic declares no contract.</p>
        ) : (
          <>
            <p className="flow-detail-contract" title={topic.contract}>
              {contract?.shortName ?? topic.contract}
            </p>
            {contract?.schema ? (
              <SchemaTree schema={contract.schema} />
            ) : (
              <p className="muted">
                No schema published by this host — rebuild it with an
                intropy-topology release that emits the contract registry to
                see the contract's fields here.
              </p>
            )}
            {contract?.fingerprint && (
              <p className="flow-detail-fingerprint" title="Schema fingerprint">
                {contract.fingerprint}
              </p>
            )}
          </>
        )}
      </Section>
    </>
  )
}

/** SchemaTree renders a contract's JSON Schema as the field tree a developer
 *  actually asks for: name, type, hierarchy, required. Constructs it does not
 *  recognize degrade to a plain type label — never an error. */
function SchemaTree({ schema }: { schema: JsonSchema }) {
  const defs = schema.$defs ?? {}
  const rows: ReactNode[] = []

  const walk = (s: JsonSchema, depth: number, seen: Set<string>): void => {
    const target = resolve(s, defs, seen)
    if (!target?.properties) return
    const required = new Set(target.required ?? [])
    for (const [name, prop] of Object.entries(target.properties)) {
      rows.push(
        <tr key={`${depth}:${name}:${rows.length}`}>
          <td className="schema-name" style={{ paddingLeft: 8 + depth * 18 }}>
            {name}
          </td>
          <td className="schema-type">{typeLabel(prop, defs)}</td>
          <td className="schema-req">
            {required.has(name) && <span className="badge-required">required</span>}
          </td>
        </tr>,
      )
      const ref = refTarget(prop)
      if (ref && seen.has(ref)) continue
      walk(prop, depth + 1, ref ? new Set(seen).add(ref) : seen)
    }
  }
  walk(schema, 0, new Set())

  if (rows.length === 0) {
    return <p className="muted">The schema declares no fields.</p>
  }
  return (
    <table className="schema-tree">
      <tbody>{rows}</tbody>
    </table>
  )
}

// refTarget names the $def a schema (or the items of an array) points at, or
// undefined for inline shapes — used to cut recursive contracts short.
function refTarget(s: JsonSchema): string | undefined {
  if (s.$ref) return defName(s.$ref)
  if (s.type === 'array' && s.items) return refTarget(s.items)
  return undefined
}

// resolve follows a schema to the object whose properties should nest under
// it: through $ref into $defs and through array items.
function resolve(
  s: JsonSchema | undefined,
  defs: Record<string, JsonSchema>,
  seen: Set<string>,
): JsonSchema | undefined {
  if (!s) return undefined
  if (s.$ref) {
    const def = defs[defName(s.$ref)]
    return def === s ? undefined : def
  }
  if (s.type === 'array') return resolve(s.items, defs, seen)
  return s
}

function defName(ref: string): string {
  return ref.slice(ref.lastIndexOf('/') + 1)
}

// typeLabel is the human-facing type column: nullability folded in ("string"
// from ["string","null"]), arrays suffixed, refs by definition name, and
// anything unrecognized shown as-is rather than hidden.
function typeLabel(s: JsonSchema | undefined, defs: Record<string, JsonSchema>): string {
  if (!s) return 'unknown'
  if (s.$ref) return defName(s.$ref)
  if (s.enum) return 'enum'
  if (Array.isArray(s.type)) {
    const types = s.type.filter((t) => t !== 'null')
    const label = types.map((t) => labelFor(t, s, defs)).join(' | ')
    return label || 'null'
  }
  return labelFor(s.type, s, defs)
}

function labelFor(
  type: string | undefined,
  s: JsonSchema,
  defs: Record<string, JsonSchema>,
): string {
  if (type === 'array') return `${typeLabel(s.items, defs)}[]`
  if (type === 'string' && s.format) return s.format
  return type ?? 'unknown'
}

function ConnectorDetail({ name, topology }: { name: string; topology: Topology }) {
  const conn: TopologyConnector | undefined = topology.connectors?.find(
    (c) => c.name === name,
  )
  const doc: MessageDoc | undefined = topology.messageDocs?.[name]

  return (
    <>
      <div className="meta-grid">
        <Meta label="Connector" value={name} />
        <Meta label="Transport" value={conn?.transport.type ?? '—'} />
        {conn?.externalSystem && (
          <Meta label="External system" value={conn.externalSystem} />
        )}
        {conn?.directions?.length ? (
          <Meta label="Direction" value={conn.directions.join(', ')} />
        ) : null}
      </div>

      <NameChips label="Used by" names={conn?.usedBy} />

      {doc ? <MessageDocView doc={doc} /> : <MessageDocEmpty topology={topology} name={name} />}
    </>
  )
}

/** MessageDocView renders an authored payload description: the structured
 *  facts, the column table, the prose, and the (author-redacted) sample. */
function MessageDocView({ doc }: { doc: MessageDoc }) {
  const facts: Array<[string, string | undefined]> = [
    ['Format', doc.format],
    ['Delimiter', doc.delimiter],
    ['Encoding', doc.encoding],
    ['File pattern', doc.filePattern],
    ['Frequency', doc.frequency],
    ['Contact', doc.contact],
  ]
  const present = facts.filter((f): f is [string, string] => Boolean(f[1]))

  return (
    <>
      <Section title="Message" icon={TuneIcon}>
        {doc.lastReviewed && <ReviewedBadge date={doc.lastReviewed} />}
        {present.length > 0 ? (
          <table className="kv">
            <tbody>
              {present.map(([k, v]) => (
                <tr key={k}>
                  <th>{k}</th>
                  <td>{v}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p className="muted">No structured facts recorded.</p>
        )}
      </Section>

      {doc.fields && doc.fields.length > 0 && (
        <Section title="Fields" icon={CategoryIcon}>
          <table className="schema-tree">
            <tbody>
              {doc.fields.map((f, i) => (
                <tr key={`${f.name}:${i}`}>
                  <td className="schema-name">
                    {f.position ? `${f.position}. ` : ''}
                    {f.name}
                  </td>
                  <td className="schema-type">{f.type ?? ''}</td>
                  <td className="schema-req">
                    {f.required && <span className="badge-required">required</span>}
                  </td>
                  <td className="schema-notes">{f.notes ?? ''}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Section>
      )}

      {doc.body && (
        <Section title="Notes" icon={DescriptionIcon}>
          <pre className="doc">{doc.body}</pre>
        </Section>
      )}

      {doc.sample?.inline && (
        <Section title="Sample" icon={CloudIcon}>
          <pre className="doc">{doc.sample.inline}</pre>
        </Section>
      )}
    </>
  )
}

/** The empty state doubles as the authoring onboarding: where to put the file
 *  and what to write in it. */
function MessageDocEmpty({ topology, name }: { topology: Topology; name: string }) {
  const dir = topology.path === '.' ? '' : `${topology.path}/`
  const today = new Date().toISOString().slice(0, 10)
  const template = `---
format: csv
delimiter: ";"
encoding: utf-8
filePattern: "*.csv"
frequency: describe when it arrives
fields:
  - name: FIELD_NAME
    type: string
    notes: what this column carries
sample:
  inline: "one;example;line"
  redacted: true
contact: who owns the source system
lastReviewed: ${today}
---
Free prose: where the data comes from, quirks, dedupe keys, gotchas.
`
  return (
    <Section title="Message" icon={DescriptionIcon}>
      <p className="muted">
        No message description yet. Describe what flows through this connector
        in <code>{dir}messages/{name}.md</code>:
      </p>
      <pre className="doc">{template}</pre>
    </Section>
  )
}

// ReviewedBadge is the staleness story of an authored doc: it renders how
// long ago the author last vouched for it.
function ReviewedBadge({ date }: { date: string }) {
  const parsed = Date.parse(date)
  let ago = ''
  if (!Number.isNaN(parsed)) {
    const days = Math.floor((Date.now() - parsed) / 86_400_000)
    if (days >= 0) {
      if (days < 1) ago = 'today'
      else if (days < 61) ago = `${days} day${days === 1 ? '' : 's'} ago`
      else ago = `${Math.floor(days / 30.44)} months ago`
    }
  }
  return (
    <p className="flow-detail-reviewed" title={date}>
      reviewed {ago || date}
    </p>
  )
}

function NameChips({ label, names }: { label: string; names?: string[] }) {
  if (!names?.length) return null
  return (
    <div className="flow-detail-chips">
      <span className="meta-label">{label}</span>
      <ul className="chips">
        {names.map((n) => (
          <li key={n} className="chip">
            {n}
          </li>
        ))}
      </ul>
    </div>
  )
}
